#include "primitives/memory/memory.hpp"

#include <algorithm>
#include <bit>

#include "primitives/rng/philox.hpp"

namespace loadforge::primitives::memory {
namespace {

static_assert(std::endian::native == std::endian::little,
              "the digest reads the generated bytes as little-endian words");

struct RunContext {
  const Config* config;
  std::span<std::uint64_t> scratch;
  std::uint64_t words_per_slot;
  std::span<std::uint64_t> partials;
};

void run_unit(void* context, std::size_t index, std::size_t slot) noexcept {
  auto& run_context = *static_cast<RunContext*>(context);
  const std::span<std::uint64_t> mine =
      run_context.scratch.subspan(slot * run_context.words_per_slot, run_context.words_per_slot);
  run_context.partials[index] = unit_digest(*run_context.config, index, mine);
}

}  // namespace

core::Result<std::uint64_t, ConfigError> scratch_words(const Config& config) noexcept {
  if (config.bytes % kWordBytes != 0) {
    return ConfigError::kBytesNotWholeWords;
  }
  return 2 * (config.bytes / kWordBytes);
}

std::uint64_t unit_digest(const Config& config, std::uint64_t unit,
                          std::span<std::uint64_t> scratch) noexcept {
  const std::size_t words = config.bytes / kWordBytes;
  const std::span<std::uint64_t> source = scratch.first(words);
  const std::span<std::uint64_t> destination = scratch.subspan(words, words);
  rng::fill_stream(config.seed, unit, std::as_writable_bytes(source));
  std::uint64_t digest = 0;
  for (std::uint64_t pass = 0; pass < config.passes; ++pass) {
    std::copy(source.begin(), source.end(), destination.begin());
    std::uint64_t sum = 0;
    for (const std::uint64_t word : destination) {
      sum += word;
    }
    digest += std::rotl(sum, static_cast<int>(pass % 64));
  }
  return digest;
}

core::Result<std::uint64_t, ConfigError> run(worker::Executor& executor, const Config& config,
                                             std::span<std::uint64_t> scratch,
                                             std::span<std::uint64_t> partials) noexcept {
  const core::Result<std::uint64_t, ConfigError> words = scratch_words(config);
  if (!words.has_value()) {
    return words.error();
  }
  const std::uint64_t per_slot = words.value();
  if (per_slot != 0 && scratch.size() / per_slot < executor.threads()) {
    return ConfigError::kScratchTooSmall;
  }
  RunContext context{&config, scratch, per_slot, partials};
  executor.run(partials.size(), run_unit, &context);
  std::uint64_t total = 0;
  for (const std::uint64_t partial : partials) {
    total += partial;
  }
  return total;
}

}  // namespace loadforge::primitives::memory
